import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import squizInfoMock from '@ntgovernment/squiz-factory/plugins/squizInfo.mock';
import comp from './main.js';

/**
 * Shaped to match the real MatrixAssetSchema, confirmed live via
 * dxp-inspector against a real Squiz DXP backend this session -- `contents`
 * is a real field `fns.resolveUri()` returns, populated for a real
 * Bodycopy asset with saved body content, empty for a Content Page (no
 * legacy raw-content storage). See content-nester.spec.md assumption 1.
 */
function fakeBodycopy({ id, contents }) {
  return {
    id: String(id),
    type: 'bodycopy',
    type_name: 'Bodycopy',
    name: 'Page Contents',
    url: `https://example.com/pages/${id}`,
    metadata: null,
    contents,
    child_count: 0,
  };
}

function fakeContentPage({ id }) {
  return {
    id: String(id),
    type: 'page_content',
    type_name: 'Content Page',
    name: 'Placeholder content page',
    url: `https://example.com/pages/${id}`,
    metadata: {},
    contents: '',
    child_count: 0,
  };
}

const FAKE_ASSETS = {
  'matrix-asset://ntg/9001': fakeBodycopy({
    id: 9001,
    contents:
      '<h2>Placeholder nested heading</h2><p>Placeholder nested paragraph text, standing in for whatever WYSIWYG body content the picked asset actually holds.</p><ul><li>Placeholder list item one</li><li>Placeholder list item two</li></ul><p>A second placeholder paragraph with a <a href="#">placeholder link</a> inside it.</p>',
  }),
  'matrix-asset://ntg/9002': fakeContentPage({ id: 9002 }),
};

function resolveUriMock(uri) {
  return FAKE_ASSETS[uri] ?? null;
}

const squiz = squizStoryRenderer(comp.main);
const mockInfo = squizInfoMock({ mock: { resolveUri: resolveUriMock } });

export default {
  title: 'dxp components/Content Nester',
};

const populatedArgs = {
  asset: 'matrix-asset://ntg/9001',
};
const populatedHtml = await squiz.markup(populatedArgs, mockInfo);

export const Populated = {
  render: (args) => squiz(args, mockInfo),
  args: populatedArgs,
  argTypes: {
    asset: {
      control: 'text',
      description: 'matrix-asset-uri for the asset to nest. Only these demo URIs resolve to anything in this Storybook preview (mocked): matrix-asset://ntg/9001 (a Bodycopy asset with real content), matrix-asset://ntg/9002 (a Content Page with empty content).',
    },
  },
  parameters: {
    docs: {
      description: { story: 'The picked asset resolves and its `contents` field (from `fns.resolveUri()`) is non-empty -- renders that HTML inline, with baseline paragraph/heading/list spacing restored.' },
      source: { code: populatedHtml, language: 'html', type: 'code' },
    },
  },
};

const emptyContentsArgs = {
  asset: 'matrix-asset://ntg/9002',
};
const emptyContentsHtml = await squiz.markup(emptyContentsArgs, mockInfo);

export const EmptyContents = {
  render: () => squiz(emptyContentsArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'The picked asset resolves, but its `contents` field is empty (e.g. a Content Page, which has no legacy raw-content storage) -- renders nothing.' },
      source: { code: emptyContentsHtml, language: 'html', type: 'code' },
    },
  },
};

const noAssetSelectedArgs = {};
const noAssetSelectedHtml = await squiz.markup(noAssetSelectedArgs, mockInfo);

export const NoAssetSelected = {
  render: () => squiz(noAssetSelectedArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'No `asset` selected -- renders nothing, never throws.' },
      source: { code: noAssetSelectedHtml, language: 'html', type: 'code' },
    },
  },
};
