import { componentAttrs } from "../_utils/component.helper";

/**
 * Content Nester DXP Component -- Server-Side Renderer
 *
 * DXP-edge equivalent of classic Matrix's "Nested Content" component --
 * renders a picked asset's own content inline on the current page. New
 * Content Pages have no native nested-content mechanism; this fills that
 * gap for asset types that still carry raw body content via
 * `resolveUri()`'s `contents` field (confirmed live against a real Squiz
 * DXP backend: populated for a real Bodycopy "Page Contents" asset once it
 * has WYSIWYG body content saved; empty for a Content Page, which has no
 * legacy raw-content storage). See content-nester.spec.md assumption 1.
 */

export default {
  async main(input = {}, info = {}) {
    const { asset = "" } = input;
    const contents = await resolveContents(asset, info?.fns);

    if (!contents) return "";

    return /*html*/ `
<div ${componentAttrs("content-nester", input)}>
  ${contents}
</div>
`;
  },
};

/**
 * fns.resolveUri wraps its result in a { ok, data } envelope -- same
 * convention as card/document/topic-listing's own unwrapResolved(). Any
 * failure (blank asset, unresolvable uri, missing fns, empty contents)
 * yields "" rather than throwing -- the component simply renders nothing.
 */
async function resolveContents(asset, fns) {
  if (!asset || typeof fns?.resolveUri !== "function") return "";
  try {
    const result = await fns.resolveUri(asset);
    const resolved = unwrapResolved(result);
    const contents = typeof resolved?.contents === "string" ? resolved.contents.trim() : "";
    return contents;
  } catch {
    return "";
  }
}

function unwrapResolved(result) {
  if (!result || typeof result !== "object") return null;
  if ("data" in result) return result.data ?? null;
  return result;
}
